package org.genhttp.api.content.services

import org.genhttp.api.protocol.ResponseStatus

import kotlin.reflect.KClass

/**
 * Declares a response that may be generated by an operation of a service.
 *
 * Responses are usually derived from the signature of the function implementing the operation. Declaring a
 * successful response (2xx) on a function replaces the derived responses, e.g. to announce that an operation
 * responds with [ResponseStatus.Created] instead of [ResponseStatus.Ok]. If no [type] is given for such a
 * response, the type returned by the function is used.
 *
 * @property status The status of the response
 * @property description Describes the circumstances the response is generated in (empty, if not set)
 * @property type The type of the content sent with this response, if any (`Nothing::class`, if not set)
 * @property contentType The content type of the response (e.g. "image/png"), if it is not determined by the
 * serialization formats supported by the service (empty, if not set)
 */
@Documentation
@Target(AnnotationTarget.CLASS, AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.RUNTIME)
@Repeatable
@MustBeDocumented
public annotation class ApiResponse(
    val status: ResponseStatus,
    val description: String = "",
    val type: KClass<*> = Nothing::class,
    val contentType: String = ""
)
